    void myFunction() {
        int x = 10;  // 'x' is an automatic variable
        printf("x inside myFunction: %d\n", x);
    }

    int main() {
        myFunction();
        // printf("x outside myFunction: %d\n", x); // Error: x is not in scope here
        return 0;
    }
