*   **`table class="table table-bordered"`:**  Uses Bootstrap's table styling.  `table-bordered` adds borders.
*   **`<thead>` and `<tbody>`:** Standard table structure.
*   **`<th>` (Table Headers):**  Crucially, each header cell has a `data-sort` attribute. This attribute tells our JavaScript what type of sorting to apply.  Possible values:
    *   `string`: For alphabetical sorting (names, text).
    *   `number`: For numerical sorting (ages, quantities).
    *   `date`: For date sorting (YYYY-MM-DD format).  You might need to adjust the date parsing if your dates are in a different format.

**2. JavaScript (Sorting Logic)**

```javascript
const table = document.querySelector('.table');
let sortColumn = null;
let sortOrder = 1; // 1 = ascending, -1 = descending

table.querySelectorAll('th').forEach(th => {
  th.addEventListener('click', () => {
    const sortType = th.dataset.sort;
    const columnIndex = th.cellIndex;

    if (sortColumn === columnIndex) {
      sortOrder *= -1; // Toggle sort order
    } else {
      sortColumn = columnIndex;
      sortOrder = 1;
    }

    sortTable(columnIndex, sortOrder, sortType);
  });
});

function sortTable(columnIndex, sortOrder, sortType) {
  const rows = Array.from(table.querySelectorAll('tbody tr'));

  rows.sort((a, b) => {
    const cellA = a.cells[columnIndex].textContent.trim();
    const cellB = b.cells[columnIndex].textContent.trim();

    let valueA, valueB;

    switch (sortType) {
      case 'string':
        valueA = cellA.toLowerCase();
        valueB = cellB.toLowerCase();
        break;
      case 'number':
        valueA = parseFloat(cellA);
        valueB = parseFloat(cellB);
        break;
      case 'date':
        valueA = new Date(cellA);
        valueB = new Date(cellB);
        break;
      default:
        valueA = cellA;
        valueB = cellB;
    }

    if (valueA < valueB) {
      return sortOrder * -1;
    }
    if (valueA > valueB) {
      return sortOrder;
    }
    return 0;
  });

  // Clear the table body and re-append sorted rows
  table.querySelector('tbody').innerHTML = '';
  rows.forEach(row => table.querySelector('tbody').appendChild(row));
}
```

